prts.feedbackvariables:
c(t):=C*t;

an1:ev(ans1,tt=3);
varsl:listofvars(expand(an1));
bvars:sort(listify(setdifference(setify(varsl),setify([x,c]))));
an1:expand(an1);

wvars:setify([X,t,T,x1,X1,x2,X2]);
wcon:setify([C1,k1,K1,A,a,C])

for i:1 while i<=length(bvars) do (if elementp(bvars[i],wvars) then  an1:ev(an1,bvars[i]=x) else (if elementp(bvars[i],wcon) then  an1:ev(an1,bvars[i]=c)));

assume(x > 0);
stu:expand(ev((x*diff(an1,x)-1)*log(x)-n1*an1,simp));
intv:ev(an1,x=e^n2);
